"""Offline evidence viewer generated only from completed measured comparison data."""
import argparse
import json
from pathlib import Path


def render(path):
    out=Path(path).parent;data=json.loads(Path(path).read_text())
    if not data['complete']:raise ValueError('A final scorecard requires every job to finish')
    script=json.dumps(data).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AgentKernel | Measured cloud evidence</title>
<style>body{font:15px system-ui;background:#101e1c;color:#e0ece6;margin:0}main{max-width:1150px;margin:auto;padding:45px 24px}h1{font-size:38px;letter-spacing:-1px}p{color:#a2b9af;line-height:1.7}.tag{color:#82dcad;font-size:12px;letter-spacing:2px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card,section{background:#172c26;border:1px solid #335343;border-radius:12px;padding:24px;margin-top:22px}.big{font-size:40px;color:#b0e5b6}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}td,th{padding:14px 9px;border-bottom:1px solid #35513f}th{color:#91b49d}.scroll{overflow:auto}button{border:1px solid #51785d;border-radius:7px;color:#cbe5c9;background:#264631;padding:10px 18px;cursor:pointer}pre{white-space:pre-wrap;font-size:11px}details{margin-top:20px}strong{color:#d5eccc}footer{margin-top:30px;color:#8ca78d;font-size:12px}@media(max-width:720px){.grid{grid-template-columns:1fr}h1{font-size:30px}}</style>
<main><div class="tag">AGENTKERNEL / REAL NEBIUS CALLS</div><h1>Measured repairs. Every gate retained.</h1><p>A frozen comparison of Super-only, Ultra-only and cloud adaptive routing on eight existing synthetic program designs. No cached proposals, local specialist, or reference repairs in prompts.</p><div class="grid" id="cards"></div><section><h2>Cost, tokens and latency</h2><div class="scroll"><table><thead><tr><th>Route</th><th>Verified</th><th>Tokens</th><th>USD</th><th>Median end to end</th><th>Ultra calls</th><th>Rejected false-fix candidates</th></tr></thead><tbody id="totals"></tbody></table></div></section><section><h2>Every outcome</h2><p>Verified requires original tests, 100 stress runs, semantics, and three ThreadSanitizer executions. Rejected candidates and unknowns stay visible.</p><div class="scroll"><table><thead><tr><th>Program</th><th>Route</th><th>Outcome</th><th>Calls</th><th>Tokens</th><th>USD</th><th>Latency</th></tr></thead><tbody id="cases"></tbody></table></div></section><section><h2>What this supports</h2><p>This comparison measures this suite and implementation. An adaptive route can recover smaller-model failures while spending more than a direct larger-model call. A small single-pass suite cannot establish statistical superiority or production generalization.</p><button id="export">Download measured JSON</button><details><summary>Protocol and interpretation</summary><p>Super uses a 4,096-token output cap; Ultra uses 8,192 in both standalone and adaptive arms. Each call is limited to 12,000 input tokens. Maximum 32 paid calls, with an established aggregate charge ceiling below $1. No post-result prompt, source, cap or policy adjustments. Two independent jobs could run concurrently, so latency includes shared-service/network effects.</p></details></section><footer>Offline read-only report. These are recorded real results, not a new live repair request. This file contains no account credentials.</footer></main>
<script id="data" type="application/json">DATA_PLACEHOLDER</script><script>
const d=JSON.parse(document.getElementById('data').textContent);const names={super_only:'Super-only',ultra_only:'Ultra-only',fast:'Cloud adaptive'};const fmt=(x,n=2)=>x==null?'Unknown':Number(x).toFixed(n);function el(t,text){const e=document.createElement(t);e.textContent=text;return e}function row(target,values){const tr=el('tr','');values.forEach(v=>tr.appendChild(el('td',String(v))));document.getElementById(target).appendChild(tr)}
for(const [k,v] of Object.entries(d.aggregates)){const card=el('div','');card.className='card';card.appendChild(el('h3',names[k]));const big=el('div',v.verified+' / 8 verified');big.className='big';card.appendChild(big);card.appendChild(el('p',v.calls+' model calls · '+v.unknown+' unknown outcomes'));document.getElementById('cards').appendChild(card);row('totals',[names[k],v.verified+'/8',v.tokens??'Unknown',fmt(v.cost_usd,6),fmt(v.median_e2e_ms/1000)+' s',v.ultra_calls,v.false_fix_candidates])}
d.rows.sort((a,b)=>(a.case+a.arm).localeCompare(b.case+b.arm)).forEach(r=>row('cases',[r.case,names[r.arm],r.status,r.model_calls??0,r.tokens??'Unknown',fmt(r.cost_usd,6),r.end_to_end_ms==null?'Unknown':fmt(r.end_to_end_ms/1000)+' s']));document.getElementById('export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='agentkernel-cloud-comparison.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
</script>'''
    (out/'SCORECARD.html').write_text(html.replace('DATA_PLACEHOLDER',script),encoding='utf-8')
    print(out/'SCORECARD.html')


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('comparison',type=Path);render(p.parse_args().comparison)
